import { test, expect } from '@playwright/test';

test.describe('Panel de ordenes', () => {
  test('la orden suspendida queda marcada en la cola', async ({ page, request }) => {
    await page.goto('/panel/ordenes');

    const res = await request.get('/api/ordenes?estado=suspendida');
    expect(res.ok()).toBe(true);

    const body = await res.json();
    const orden = body.items.find((o: { id: number }) => o.id === 187);
    expect(orden).toBeDefined();
    expect(orden.isSuspended).toBe(true);
    expect(orden.motivo).toBe('EMB');

    const detalle = await request.get('/api/ordenes/187');
    expect(detalle.status()).toBe(200);
    expect((await detalle.json()).badge).toBe('incidencia');
  });
});

