import { test, expect } from '@playwright/test';

test('registrar incidencia desde el modal de la orden', async ({ page }) => {
  await page.route(/\/api\/incidencias(\?.*)?$/, (route) =>
    route.fulfill({ status: 201, contentType: 'application/json', body: JSON.stringify({ id: 991, estado: 'abierta' }) }),
  );
  await page.route('**/api/catalogos/motivos-incidencia', (route) =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify([{ id: 3, nombre: 'Embalaje danado' }]) }),
  );

  await page.goto('/panel/ordenes/187');
  await page.getByTestId('orden-registrar-incidencia').click();
  await expect(page.getByTestId('incidencia-modal')).toBeVisible();
  await page.getByTestId('incidencia-motivo').selectOption('3');
  await page.getByTestId('incidencia-detalle').fill('Bolsa abierta al recibir');
  await page.getByTestId('incidencia-confirmar').click();
  await expect(page.getByTestId('incidencia-badge')).toBeVisible();
  await expect(page.getByTestId('incidencia-badge')).toContainText('abierta');
});

import { test, expect } from '@playwright/test';

test('registrar incidencia desde el modal de la orden', async ({ page, request }) => {
  const seed = await request.post('/api/ordenes', {
    data: { id: 187, cliente: 'Deposito Norte', estado: 'en-curso' },
  });
  expect(seed.ok()).toBe(true);

  await page.goto('/panel/ordenes/187');
  await page.getByTestId('orden-registrar-incidencia').click();
  await expect(page.getByTestId('incidencia-modal')).toBeVisible();
  await page.getByTestId('incidencia-motivo').selectOption('3');
  await page.getByTestId('incidencia-detalle').fill('Bolsa abierta al recibir');
  await page.getByTestId('incidencia-confirmar').click();
  await expect(page.getByTestId('incidencia-modal')).toBeHidden();
  await expect(page.getByTestId('incidencia-badge')).toBeVisible();
  await expect(page.getByTestId('incidencia-badge')).toContainText('abierta');
});
